using System;using System.Text;using System.Collections.Generic;using OpenMetaverse;using OpenMetaverse.StructuredData;using OpenSim.Framework;
public class AccessContext{public OSDMap command;public string trace="";public int gods,lands;public bool F(string key,bool fallback=false)=>command.ContainsKey(key)?command[key].AsBoolean():fallback;public int N(string key,int fallback=0)=>command.ContainsKey(key)?command[key].AsInteger():fallback;public void Log(string op,string value=""){trace+=op+":"+ScenePolicy.H(value)+";";if(command["failure"].AsString()==op)throw new Exception(op);}}
public class AccessPermissions{AccessContext c;public AccessPermissions(AccessContext ctx){c=ctx;}public bool IsGod(UUID a){c.Log("god",a.ToString());++c.gods;return c.F("god")||(c.N("god_after")>0&&c.gods>=c.N("god_after"));}public bool IsEstateManager(UUID a){c.Log("manager",a.ToString());return c.F("manager");}}
public interface ILandObject{bool IsBannedFromLand(UUID a);bool IsRestrictedFromLand(UUID a);bool IsEitherBannedOrRestricted(UUID a);Vector2? GetNearestPoint(Vector3 p);}
public class AccessParcel:ILandObject{AccessContext c;int mode;public AccessParcel(AccessContext ctx,int m){c=ctx;mode=m;}public bool IsBannedFromLand(UUID a){c.Log("banned",a.ToString());return mode==2||mode==4;}public bool IsRestrictedFromLand(UUID a){c.Log("restricted",a.ToString());return mode==3||mode==4;}public bool IsEitherBannedOrRestricted(UUID a){c.Log("either",a.ToString());return mode>=2;}public Vector2? GetNearestPoint(Vector3 p){c.Log("point",ScenePolicy.B(p.X)+":"+ScenePolicy.B(p.Y));var value=c.command["point"] as OSDArray;return value==null?null:new Vector2((float)value[0].AsReal(),(float)value[1].AsReal());}}
public class AccessLand{AccessContext c;public AccessLand(AccessContext ctx){c=ctx;}public ILandObject GetLandObject(float x,float y){c.Log("land",ScenePolicy.B(x)+":"+ScenePolicy.B(y));var values=c.command["lands"] as OSDArray;int mode=values==null||values.Count==0?1:values[Math.Min(c.lands,values.Count-1)].AsInteger();++c.lands;return mode==0?null:new AccessParcel(c,mode);}}
public class AccessEstate{AccessContext c;public AccessEstate(AccessContext ctx){c=ctx;}public bool IsBanned(UUID a,int f){c.Log("estate-ban",a+":"+f);return c.F("estate_banned");}public bool PublicAccess{get{c.Log("public");return c.F("public",true);}}public bool HasAccess(UUID a){c.Log("estate-access",a.ToString());return c.F("access");}public UUID[] EstateGroups{get{c.Log("estate-groups");var values=c.command["estate_groups"] as OSDArray;if(values==null)return null;var result=new UUID[values.Count];for(int i=0;i<result.Length;i++)result[i]=ScenePolicy.Id(values[i].AsInteger());return result;}}public bool AllowDirectTeleport{get{c.Log("direct");return c.F("direct",true);}}}
public class SpawnPoint{AccessContext c;OSDArray value;int index;public SpawnPoint(AccessContext ctx,OSDArray v,int n){c=ctx;value=v;index=n;}public Vector3 GetLocation(Vector3 origin,Quaternion rotation){c.Log("spawn",index.ToString());return new Vector3((float)value[0].AsReal(),(float)value[1].AsReal(),(float)value[2].AsReal());}}
public class AccessSettings{AccessContext c;public int AgentLimit;public UUID TelehubObject;public AccessSettings(AccessContext ctx){c=ctx;AgentLimit=c.N("limit",100);TelehubObject=c.F("hub")?ScenePolicy.Id(6):UUID.Zero;}public List<SpawnPoint> SpawnPoints(){c.Log("spawns");var result=new List<SpawnPoint>();var values=c.command["spawns"] as OSDArray;if(values!=null)for(int i=0;i<values.Count;i++)result.Add(new SpawnPoint(c,(OSDArray)values[i],i));return result;}}
public class AccessRegion{public UUID RegionID=ScenePolicy.Id(9),ScopeID=ScenePolicy.Id(8);public string RegionName;public uint RegionSizeX,RegionSizeY;public AccessEstate EstateSettings;public AccessSettings RegionSettings;public AccessRegion(AccessContext c){RegionName=c.F("null_name")?null:"Region";RegionSizeX=(uint)c.N("size_x",256);RegionSizeY=(uint)c.N("size_y",256);EstateSettings=c.F("null_estate")?null:new AccessEstate(c);RegionSettings=new AccessSettings(c);}}
public class SceneObjectGroup{AccessContext c;public SceneObjectGroup(AccessContext ctx){c=ctx;}public Vector3 AbsolutePosition{get{c.Log("hub-position");return new Vector3(10,20,30);}}public Quaternion GroupRotation{get{c.Log("hub-rotation");return Quaternion.Identity;}}}
public class AccessStats{AccessContext c;public AccessStats(AccessContext ctx){c=ctx;}public void RecalculateStats()=>c.Log("recalculate");public int GetRootAgentCount(){c.Log("roots");return c.N("roots");}public int GetRootNPCCount(){c.Log("npcs");return c.N("npcs");}}
public class AccessCircuits{AccessContext c;public AgentCircuitData existing;public AccessCircuits(AccessContext ctx){c=ctx;if(c.F("circuit"))existing=new AgentCircuitData{AgentID=ScenePolicy.Id(c.N("circuit_agent",7)),firstname=c.F("null_names")?null:"Existing",lastname=c.F("null_names")?null:"Agent"};}public AgentCircuitData GetAgentCircuitData(UUID a){c.Log("circuit",a.ToString());return existing;}}
public class AccessAuthorization{AccessContext c;AccessCircuits circuits;public AccessAuthorization(AccessContext ctx,AccessCircuits a){c=ctx;circuits=a;}public bool IsAuthorizedForRegion(string a,string f,string l,string r,out string reason){c.Log("authorize",a+":"+(f==null?"-":ScenePolicy.H(f))+":"+(l==null?"-":ScenePolicy.H(l))+":"+r+":"+(circuits.existing!=null&&circuits.existing.AgentID.ToString()==a?"1":"0"));reason="auth-reason";return !c.F("auth_deny");}}
public class GroupMembershipData{public UUID GroupID;}
public class AccessGroups{AccessContext c;public AccessGroups(AccessContext ctx){c=ctx;}public GroupMembershipData[] GetMembershipData(UUID a){c.Log("memberships",a.ToString());var values=c.command["memberships"] as OSDArray;if(values==null)return null;var result=new GroupMembershipData[values.Count];for(int i=0;i<result.Length;i++)result[i]=values[i].Type==OSDType.Unknown?null:new GroupMembershipData{GroupID=ScenePolicy.Id(values[i].AsInteger())};return result;}}
public static class Constants{public static UUID servicesGodAgentID=new UUID("6571e388-6218-4574-87db-f9379718315e");}
public class AccessLog{public void DebugFormat(string s,params object[] args){}public void WarnFormat(string s,params object[] args){}public void ErrorFormat(string s,params object[] args){}}
public partial class ScenePolicy{AccessContext c;AccessPermissions Permissions;bool m_strictAccessControl,AllowAvatarCrossing;AccessRegion RegionInfo;AccessCircuits m_authenticateHandler;AccessAuthorization AuthorizationService;AccessGroups m_groupsModule;AccessStats m_sceneGraph;AccessLand LandChannel;AccessLog m_log=new();public ScenePolicy(AccessContext ctx){c=ctx;Permissions=new(c);m_strictAccessControl=c.F("strict",true);AllowAvatarCrossing=c.F("cross",true);RegionInfo=new(c);m_authenticateHandler=new(c);AuthorizationService=c.F("auth")?new(c,m_authenticateHandler):null;m_groupsModule=c.F("groups")?new(c):null;m_sceneGraph=new(c);LandChannel=new(c);}int GetUserFlags(UUID a){c.Log("flags",a.ToString());return c.N("flags",42);}SceneObjectGroup GetSceneObjectGroup(UUID a){c.Log("telehub",a.ToString());return c.F("missing_hub")?null:new(c);}ILandObject GetNearestAllowedParcel(UUID a,float x,float y){c.Log("nearest",a+":"+B(x)+":"+B(y));return c.F("nearest")?new AccessParcel(c,1):null;}public static UUID Id(int n)=>new UUID("00000000-0000-0000-0000-00000000000"+n);public static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();public static string B(float f)=>(float.IsNaN(f)?0x7fc00000u:BitConverter.SingleToUInt32Bits(f)).ToString("x8");
public static void Main(){Culture.SetCurrentCulture();string line;while((line=Console.ReadLine())!=null){var c=new AccessContext{command=(OSDMap)OSDParser.DeserializeJson(Encoding.UTF8.GetString(Convert.FromHexString(line)))};var scene=new ScenePolicy(c);UUID agent=c.F("service_agent")?Constants.servicesGodAgentID:Id(7);Vector3 position=new(1,2,30);if(c.command["position"] is OSDArray v)position=new((float)v[0].AsReal(),(float)v[1].AsReal(),(float)v[2].AsReal());float x=position.X,y=position.Y;string reason="before",result;var features=new List<UUID>{Id(8)};try{bool ok;switch(c.command["op"].AsString()){case "authorize":var circuit=scene.m_authenticateHandler.existing??new AgentCircuitData{AgentID=agent,firstname="",lastname=""};ok=scene.AuthorizeUser(c.F("null_agent")?null:circuit,c.F("bypass"),out reason);break;case "land":ok=scene.CheckLandPositionAccess(agent,c.F("teleport",true),c.F("check_hub",true),c.F("check_count",true),position,out reason);break;case "restrictions":ok=scene.TestLandRestrictions(agent,out reason,ref x,ref y);break;default:ok=scene.QueryAccess(agent,null,c.F("teleport",true),position,features,out reason);break;}result=ok?"1":"0";}catch{result="EX";}Console.WriteLine(result+"|"+H(reason)+"|"+H(c.trace)+"|"+B(x)+":"+B(y)+"|"+features.Count);}}}
